        throw new UOE(
            "Cannot add overlapping segments [%s and %s] with the same version [%s]",
            currKey,
            entryInterval,
            entry.getVersion()
        );
      }
    }

    currKey = nextKey;
    retVal = true;
  }

  addIntervalToTimeline(entryInterval, entry, timeline);

  return retVal;
}

