      lock.getReadHoldCount() > 0 || lock.isWriteLockedByCurrentThread(),
      "timeline must be locked during visible holder copy"
  );
  final boolean skipNoData = skipObjectsWithNoData;
  if (skipEmpty && skipNoData && !partitionHolder.hasData()) {
    return null;
  }

  DateTime timelineStart = timelineInterval.getStart();
  DateTime timelineEnd = timelineInterval.getEnd();
  DateTime queryStart = queryInterval.getStart();
  DateTime queryEnd = queryInterval.getEnd();
  if (!(timelineStart.getMillis() < queryEnd.getMillis() && queryStart.getMillis() < timelineEnd.getMillis())) {
    return null;
  }

