  for (PartitionChunk<ObjectType> chunk : partitionHolder) {
    visibleChunks.add(chunk);
  }
  TimelineObjectHolder<VersionType, ObjectType> holder = new TimelineObjectHolder<>(
      timelineInterval,
      trueInterval,
      version,
      new PartitionHolder<>(visibleChunks)
  );

