    } else {
      clipped = new Interval(overlapStart.getMillis(), overlapEnd.getMillis(), holderInterval.getChronology());
    }
    return new TimelineObjectHolder<>(
        clipped,
        holder.getTrueInterval(),
        holder.getVersion(),
        holder.getObject()
    );
  }
